-- Opening questions and guided solutions for PC-AC Portuguese lessons.
-- Original practice questions in exam style; not transcriptions of official exams.
with lessons(slug,title,question,options,answer,solution) as (
 values ($q$pcac-2026-portugues-01-leitura-compreensao-interpretacao$q$,$q$Inferência e informação explícita$q$,$q$Leia: “Embora o sistema tenha sido restabelecido às 14h, o atendimento permaneceu suspenso até a conferência dos registros.” É correto inferir que:$q$,$q$["A) o atendimento voltou exatamente às 14h.","B) a normalização do sistema não foi suficiente para retomar imediatamente o atendimento.","C) os registros foram destruídos.","D) o sistema permaneceu fora do ar após as 14h.","E) a conferência ocorreu antes da falha."]$q$::jsonb,$q$B$q$,$q$O conectivo “embora” introduz concessão: o sistema voltou às 14h, mas havia outra condição para retomar o atendimento, a conferência dos registros. A alternativa B respeita essa relação. Não acrescente informações que o texto não fornece, como destruição de registros ou horário exato da conferência.$q$),
($q$pcac-2026-portugues-02-estrutura-textual-progressao-ideias$q$,$q$Tópico frasal e progressão$q$,$q$Em um parágrafo, a frase inicial apresenta a ideia de que a preservação de evidências digitais exige procedimentos documentados. As frases seguintes explicam coleta, armazenamento e registro de acesso. A função da frase inicial é:$q$,$q$["A) apresentar o tópico central do parágrafo.","B) concluir o texto inteiro.","C) introduzir uma ideia sem relação com as demais.","D) contradizer os exemplos.","E) funcionar como citação obrigatória."]$q$::jsonb,$q$A$q$,$q$A frase inicial apresenta a ideia central ou tópico frasal. As frases seguintes desenvolvem essa ideia com explicações e exemplos. Para reconhecer a estrutura, pergunte qual afirmação resume o parágrafo e como as demais frases a sustentam.$q$),
($q$pcac-2026-portugues-03-articulacao-referencias-conectivos$q$,$q$Referência pronominal$q$,$q$Em “A equipe recolheu os documentos e os encaminhou ao setor técnico”, o pronome “os” retoma:$q$,$q$["A) a equipe.","B) os documentos.","C) o setor técnico.","D) o recolhimento.","E) o encaminhamento."]$q$::jsonb,$q$B$q$,$q$O pronome oblíquo “os” está no masculino plural e funciona como objeto direto de “encaminhou”. Retoma “os documentos”. Para localizar referentes, observe concordância, função sintática e sentido do período; não escolha apenas pelo termo mais próximo.$q$),
($q$pcac-2026-portugues-04-coesao-coerencia-textual$q$,$q$Conectivo de oposição$q$,$q$Assinale o conectivo que melhor completa: “Os dados foram coletados corretamente; _____, a análise apresentou limitações.”$q$,$q$["A) portanto.","B) além disso.","C) contudo.","D) porque.","E) assim."]$q$::jsonb,$q$C$q$,$q$“Contudo” estabelece oposição ou contraste entre coleta correta e limitações da análise. “Portanto” indicaria conclusão; “além disso”, adição; “porque”, causa. Identifique a relação lógica pretendida antes de escolher o conectivo.$q$),
($q$pcac-2026-portugues-05-reescrita-equivalencia-paralelismo$q$,$q$Equivalência de sentido na reescrita$q$,$q$A frase “Embora estivesse cansada, a servidora concluiu o relatório” mantém o sentido se reescrita como:$q$,$q$["A) Como estava cansada, não concluiu o relatório.","B) Estava cansada; por isso, interrompeu o relatório.","C) Apesar do cansaço, a servidora concluiu o relatório.","D) A servidora concluiu o relatório porque estava cansada.","E) Se estivesse cansada, concluiria o relatório."]$q$::jsonb,$q$C$q$,$q$“Embora” expressa concessão e pode ser substituído por “apesar de” mantendo a ideia de contraste. As demais alternativas introduzem causa, consequência ou condição, alterando o sentido. Em reescrita, preserve relação lógica, tempo verbal e informação essencial.$q$),
($q$pcac-2026-portugues-06-semantica-sinonimia-ambiguidade$q$,$q$Ambiguidade$q$,$q$A frase “O policial informou ao delegado que seu relatório estava incompleto” é ambígua porque:$q$,$q$["A) não possui verbo.","B) “seu” pode retomar o relatório do policial ou do delegado, conforme o contexto.","C) o sujeito é inexistente.","D) contém erro obrigatório de concordância.","E) não apresenta pronome."]$q$::jsonb,$q$B$q$,$q$O possessivo “seu” pode ter mais de um referente: o relatório do policial ou o do delegado. Para eliminar ambiguidade, substitua por “o relatório do policial” ou “o relatório do delegado”. A ambiguidade ocorre quando a estrutura permite mais de uma interpretação.$q$),
($q$pcac-2026-portugues-07-ortografia-acentuacao-pontuacao$q$,$q$Acentuação gráfica$q$,$q$Assinale a palavra corretamente acentuada segundo a ortografia oficial:$q$,$q$["A) idéia.","B) assembléia.","C) heróico.","D) saúde.","E) vôo."]$q$::jsonb,$q$D$q$,$q$“Saúde” recebe acento no u tônico do hiato, separado da vogal anterior. Pelo Acordo Ortográfico, ideia, assembleia, heroico e voo não recebem os acentos indicados nas alternativas. Atenção às mudanças do acordo em ditongos abertos de paroxítonas e em palavras com oo.$q$),
($q$pcac-2026-portugues-08-morfologia-formacao-palavras$q$,$q$Derivação prefixal$q$,$q$A palavra “infeliz” foi formada por:$q$,$q$["A) composição por justaposição.","B) derivação prefixal.","C) derivação sufixal.","D) derivação parassintética.","E) abreviação."]$q$::jsonb,$q$B$q$,$q$“Infeliz” resulta da palavra “feliz” com acréscimo do prefixo “in-”, que atribui sentido de negação. Como o acréscimo ocorre antes do radical, é derivação prefixal. Prefixo antes; sufixo depois.$q$),
($q$pcac-2026-portugues-09-classes-de-palavras$q$,$q$Pronome relativo$q$,$q$Na frase “O documento que chegou ontem será analisado”, a palavra “que” é:$q$,$q$["A) conjunção coordenativa.","B) pronome relativo, retomando “documento”.","C) artigo definido.","D) preposição.","E) advérbio de tempo."]$q$::jsonb,$q$B$q$,$q$“Que” retoma o antecedente “documento” e introduz oração subordinada adjetiva: é pronome relativo. Um teste útil é substituir por “o qual”: “o documento o qual chegou ontem”. Observe a função de retomada, não apenas a forma da palavra.$q$),
($q$pcac-2026-portugues-10-sintaxe-oracao-periodo$q$,$q$Sujeito da oração$q$,$q$Em “Chegaram ontem os novos equipamentos”, o sujeito é:$q$,$q$["A) oculto.","B) indeterminado.","C) os novos equipamentos.","D) ontem.","E) chegaram."]$q$::jsonb,$q$C$q$,$q$A ordem está invertida. Pergunte: “o que chegou?” — os novos equipamentos. O sujeito é simples e está posposto ao verbo. O verbo concorda com o núcleo plural “equipamentos”: chegaram.$q$),
($q$pcac-2026-portugues-11-concordancia-verbal-nominal$q$,$q$Concordância verbal$q$,$q$Assinale a frase correta:$q$,$q$["A) Fazem dois anos que o setor foi criado.","B) Houveram problemas no sistema.","C) Existem documentos pendentes.","D) A equipe chegaram cedo.","E) Segue anexas o relatório."]$q$::jsonb,$q$C$q$,$q$“Existir” é verbo pessoal e concorda com o sujeito plural “documentos”: existem documentos. “Fazer” indicando tempo decorrido é impessoal: faz dois anos. “Haver” no sentido de existir é impessoal: houve problemas. Em “a equipe chegou”, o verbo concorda com equipe.$q$),
($q$pcac-2026-portugues-12-regencia-pronomes-crase$q$,$q$Crase antes de palavra feminina$q$,$q$Assinale a alternativa em que o uso da crase está correto:$q$,$q$["A) O servidor entregou o relatório à chefia.","B) O servidor começou à trabalhar.","C) A equipe chegou à Brasília.","D) O documento foi enviado à todos.","E) A reunião ocorrerá à partir das 9h."]$q$::jsonb,$q$A$q$,$q$“Entregar” rege a preposição a (entregar algo a alguém) e “chefia” admite artigo feminino a; ocorre a fusão: à. Não há crase antes de verbo, pronome indefinido masculino ou na expressão “a partir”. Com nomes de lugar, verifique se admitem artigo.$q$),
($q$pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia$q$,$q$Metáfora$q$,$q$Na frase “A investigação lançou luz sobre os fatos”, a expressão “lançou luz” foi empregada em sentido figurado. Trata-se de:$q$,$q$["A) hipérbole.","B) metáfora.","C) eufemismo.","D) pleonasmo.","E) onomatopeia."]$q$::jsonb,$q$B$q$,$q$“Lançar luz” não significa iluminar fisicamente, mas esclarecer. Há transferência de sentido por semelhança: metáfora. Hipérbole exagera; eufemismo suaviza; pleonasmo repete uma ideia; onomatopeia imita sons.$q$),
($q$pcac-2026-portugues-colocacao-pronominal$q$,$q$Próclise e palavra atrativa$q$,$q$Assinale a frase em que a colocação pronominal está adequada à norma-padrão:$q$,$q$["A) Não informou-me sobre a alteração.","B) Não me informou sobre a alteração.","C) Informaria-me não sobre a alteração.","D) Me informou não sobre a alteração.","E) Não informou sobre a alteração-me."]$q$::jsonb,$q$B$q$,$q$A palavra negativa “não” é fator de próclise, atraindo o pronome para antes do verbo: “Não me informou”. Na norma-padrão, evite a ênclise após palavra negativa. Identifique palavras atrativas como não, nunca, ninguém, pronomes relativos e conjunções subordinativas.$q$),
($q$pcac-2026-portugues-crase-emprego-casos$q$,$q$Crase em locução adverbial feminina$q$,$q$Assinale a frase em que a crase está corretamente empregada:$q$,$q$["A) O relatório foi enviado à prazo.","B) A equipe permaneceu à disposição.","C) O servidor começou à revisar.","D) A reunião será à cada semana.","E) O documento foi entregue à ele."]$q$::jsonb,$q$B$q$,$q$“À disposição” é locução adverbial feminina e recebe crase. Não ocorre crase antes de verbo (“a revisar”), pronome pessoal (“a ele”), expressões como “a cada” nem na locução masculina “a prazo”. Memorize locuções femininas frequentes: à disposição, às vezes, à noite.$q$),
($q$pcac-2026-portugues-figuras-linguagem$q$,$q$Personificação$q$,$q$Na frase “A cidade acordou assustada com a notícia”, atribui-se à cidade uma ação ou sentimento humano. A figura de linguagem é:$q$,$q$["A) comparação.","B) personificação ou prosopopeia.","C) metonímia.","D) antítese.","E) ironia."]$q$::jsonb,$q$B$q$,$q$Personificação (prosopopeia) atribui características, sentimentos ou ações humanas a seres não humanos ou ideias abstratas. A cidade não acorda literalmente; a expressão cria efeito expressivo. Diferencie de comparação, que explicita aproximação por conectivo como “como”.$q$),
($q$pcac-2026-portugues-linguagem-digital-tecnologia$q$,$q$Gênero textual digital$q$,$q$Uma mensagem institucional enviada por e-mail, com assunto, saudação, corpo, despedida e assinatura, caracteriza-se principalmente como:$q$,$q$["A) gênero textual digital com finalidade comunicativa e estrutura própria.","B) texto sem gênero por ser eletrônico.","C) linguagem exclusivamente não verbal.","D) documento sem interlocutor.","E) gênero literário necessariamente."]$q$::jsonb,$q$A$q$,$q$O meio digital não elimina o gênero textual. O e-mail tem finalidade, interlocutores, assunto e convenções de organização. A adequação depende do contexto, grau de formalidade e destinatário. Não confunda suporte eletrônico com ausência de gênero.$q$),
($q$pcac-2026-portugues-regencia-verbal-nominal$q$,$q$Regência do verbo assistir$q$,$q$Na norma-padrão, no sentido de ver ou presenciar, o verbo “assistir” rege:$q$,$q$["A) objeto direto sem preposição.","B) preposição a: assistir ao filme.","C) preposição de: assistir do filme.","D) preposição em obrigatória.","E) preposição por."]$q$::jsonb,$q$B$q$,$q$No sentido de ver/presenciar, assistir é transitivo indireto e rege a preposição a: “assistir ao filme”, “assistir à sessão”. Em outros sentidos, a regência pode mudar: assistir alguém no sentido de prestar assistência admite objeto direto. Identifique o sentido antes de escolher a preposição.$q$),
($q$pcac-2026-portugues-variacao-linguistica-registros$q$,$q$Adequação de registro$q$,$q$Em um relatório oficial destinado à autoridade policial, a escolha linguística mais adequada é:$q$,$q$["A) usar gírias para aproximar o leitor.","B) empregar linguagem clara, objetiva e compatível com a norma-padrão e o contexto institucional.","C) reproduzir abreviações de mensagens informais sem explicação.","D) usar expressões ambíguas para resumir.","E) evitar pontuação."]$q$::jsonb,$q$B$q$,$q$A linguagem deve ser adequada ao gênero, destinatário e finalidade. Relatórios oficiais exigem clareza, objetividade, precisão e registro compatível com o contexto institucional. Variação linguística não é “erro” em si; a questão é adequação à situação comunicativa.$q$)
),
blocks as (
 select *,
 E'\n\n---\n\n# Questão de abertura — '||title||E'\n\n_Questão autoral no estilo de concursos públicos — elaborada para estudo, não é transcrição de prova oficial._\n\n**Questão:** '||question||E'\n\n'||
 (select string_agg(chr(10)||opt,' ' order by ord) from jsonb_array_elements_text(options) with ordinality x(opt,ord))||
 E'\n\n**Antes de continuar:** tente responder. Observe o contexto, a relação entre as palavras e a regra gramatical ou textual exigida.\n\n' opening,
 E'\n\n---\n\n# Resolução comentada da questão de abertura\n\n**Gabarito: '||answer||'.** '||solution||E'\n\n' closing
 from lessons
)
update public.study_materials m
set body_md=b.opening||m.body_md||b.closing,updated_at=now()
from blocks b
where m.slug=b.slug and m.contest_name='PC-AC 2026'
and m.discipline='Língua Portuguesa' and m.content_status='active'
and m.body_md not like '%# Questão de abertura —%';
